// ── UNIFIED SEND ENTRY POINT ──────────────────────────
// Guard state keeps the VN prediction prompt from reopening or re-submitting
// while Babbage is already processing. Without this, the VN click handler can
// turn one prompt into a tiny haunted carousel.
let predictionGateActive = false;
let isSubmittingToBabbage = false;

// ══════════════════════════════════════════════════════
//  SEND
// ══════════════════════════════════════════════════════
async function send() {
  if (scenarioIndex === SCENARIO_INDEX.CONTENT_AVALANCHE && typeof sendGuided === 'function') {
    return sendGuided();
  }
  return false;
}


function pcSetBabbageSubmitting(value) {
  isSubmittingToBabbage = !!value;
  window.isSubmittingToBabbage = !!value;
}

async function sendMain(text) {
  if (!text || isSubmittingToBabbage) return;
  if (scenarioIndex !== SCENARIO_INDEX.CONTENT_AVALANCHE || !getScenarioUI(scenarioIndex).implemented) return;

  const runToken = pcCaptureScenarioRun(SCENARIO_INDEX.CONTENT_AVALANCHE);
  pcSetBabbageSubmitting(true);
  attempts++;
  lastPromptText = text;
  const attEl = document.getElementById('attNum');
  if (attEl) attEl.textContent = attempts;

  history.push({ role: 'user', content: text });
  const btn = document.getElementById('sendBtn');
  if (btn) btn.disabled = true;
  addTyping();

  try {
    const data = await requestBabbageAnalysis({
      max_output_tokens: 5000,
      system: scenarios[SCENARIO_INDEX.CONTENT_AVALANCHE].system,
      messages: history
    }, 'main');
    if (!pcIsScenarioRunCurrent(runToken)) return;
    removeTyping();

    if (data.error) {
      addMsg('ai', `<span style="color:var(--red)">Error: ${esc(data.error.message || 'Babbage request failed.')}</span>`);
      return;
    }

    const reply = data.content?.[0]?.text || '';
    const structuredAnalysis = data.structured || null;
    history.push({ role: 'assistant', content: reply });

    const score = scorePrompt(text);
    const active = detectOSCQR(reply, scenarios[SCENARIO_INDEX.CONTENT_AVALANCHE].oscqr);
    trackPrompt(SCENARIO_INDEX.CONTENT_AVALANCHE, text, score.total, reply, active.map(id => {
      const indicator = scenarios[SCENARIO_INDEX.CONTENT_AVALANCHE].oscqr.find(item => item.id === id);
      return indicator ? indicator.label : id;
    }), {
      provider: data.provider || (data.mock ? 'local-fallback' : ''),
      model: data.model || '',
      request_id: data.request_id || '',
      elapsed_ms: data.elapsed_ms,
      usage: data.usage || null,
      structured: structuredAnalysis
    });

    awardScenarioScoreXP(SCENARIO_INDEX.CONTENT_AVALANCHE, score.total, 5);
    lastScore = score.total;
    showBabbageFinalResponseInTerminal(reply, !!data.mock, () => {
      addS1BabbageResultCard(reply, structuredAnalysis);
      showS1PostAnalysisReflection(score.total);
    }, score.total, data.mockReason || '', structuredAnalysis);
  } catch (error) {
    if (pcIsScenarioRunCurrent(runToken)) {
      removeTyping();
      addMsg('ai', `<span style="color:var(--red)">Something went wrong. Please try again.</span>`);
    }
  } finally {
    pcSetBabbageSubmitting(false);
    predictionGateActive = false;
    const btn = document.getElementById('sendBtn');
    if (btn) btn.disabled = false;
  }
}

// ══════════════════════════════════════════════════════
function scorePrompt(text) {
  const value = String(text || '');
  const values = (window.playerHistory && window.playerHistory.s1) || getS1GuidedValues();
  const checks = analyzeS1Guided(values);
  const hasLearners = !!checks.audience;
  const hasGoal = !!checks.issue;
  const hasContext = !!checks.interaction;
  const hasConstraint = !!checks.constraints;
  const isDetailed = !!checks.success;
  const penalty = checks.demeaning ? 2 : 0;
  return {
    hasLearners, hasGoal, hasContext, hasConstraint, isDetailed,
    demeaning: !!checks.demeaning,
    total: Math.max(0, [hasLearners, hasGoal, hasContext, hasConstraint, isDetailed].filter(Boolean).length - penalty)
  };
}


// ══════════════════════════════════════════════════════
//  HELPERS
// ══════════════════════════════════════════════════════
function parseS1BabbageStructuredResponse(text) {
  const raw = String(text || '').replace(/\r/g, '').trim();
  const headings = [
    ['status', 'STATUS'],
    ['confidence', 'CONFIDENCE'],
    ['summary', 'FEEDBACK SUMMARY'],
    ['worked', 'WHAT WORKED'],
    ['issue', 'ISSUE DETECTED'],
    ['repair', 'RECOMMENDED REPAIR'],
    ['impact', 'EXPECTED IMPACT'],
    ['draft', 'REVISED DISCUSSION PROMPT'],
    ['quality', 'COURSE QUALITY CHECK']
  ];
  const result = Object.fromEntries(headings.map(([key]) => [key, '']));
  let current = '';

  raw.split('\n').forEach(line => {
    const trimmed = line.trim();
    const normalized = trimmed
      .replace(/^#{1,4}\s*/, '')
      .replace(/^\*{1,2}|\*{1,2}$/g, '')
      .replace(/:$/, '')
      .trim()
      .toUpperCase();
    const match = headings.find(([, label]) => normalized === label);
    if (match) { current = match[0]; return; }
    if (!current) return;
    result[current] += (result[current] ? '\n' : '') + line;
  });

  Object.keys(result).forEach(key => { result[key] = result[key].trim(); });
  return result;
}

function cleanS1BabbageDraft(text) {
  const parsed = parseS1BabbageStructuredResponse(text);
  const draft = parsed.draft || String(text || '');
  return draft
    .replace(/^#{1,3}\s*Revised Discussion Prompt(?::[^\n]*)?\s*/i, '')
    .replace(/^Revised Discussion Prompt(?::[^\n]*)?\s*/i, '')
    .replace(/^Here's your redesigned discussion prompt:\s*/i, '')
    .replace(/^\s*---+\s*$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function esc(t) {
  return String(t ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

// Minimal markdown formatter used by result cards and legacy chat bubbles.
// An earlier cleanup removed this helper, which made Consult Babbage crash after the mock response returned.
function fmt(text) {
  return esc(String(text ?? ''))
    .replace(/^###\s+(.+)$/gm, '<h3>$1</h3>')
    .replace(/^##\s+(.+)$/gm, '<h3>$1</h3>')
    .replace(/^#\s+(.+)$/gm, '<h3>$1</h3>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/\n/g, '<br>');
}

function autoGrow(el) {
  if (!el) return;
  el.style.height = 'auto';

  const cap = el.id && el.id.startsWith('g-') ? 190 : 130;
  el.style.height = Math.min(el.scrollHeight, cap) + 'px';
}

function pcNormalizeProgressState(raw = {}) {
  const bestScores = Array.from({ length: SCENARIO_COUNT }, (_, index) => {
    const value = Number(raw?.bestScores?.[index] || 0);
    return Math.max(0, Math.min(5, Number.isFinite(value) ? value : 0));
  });
  const completedAwards = Array.from({ length: SCENARIO_COUNT }, (_, index) => Boolean(raw?.completedAwards?.[index]));
  const s1PracticeScores = Array.from({ length: 4 }, (_, index) => {
    const value = Number(raw?.s1PracticeScores?.[index] || 0);
    return Math.max(0, Math.min(3, Number.isFinite(value) ? value : 0));
  });
  const s1TransferScore = Math.max(0, Math.min(5, Number(raw?.s1TransferScore) || 0));
  const hasS1GranularProgress = s1PracticeScores.some(score => score > 0) || s1TransferScore > 0;
  const s1RawScore = s1PracticeScores.reduce((total, score) => total + score, 0) + s1TransferScore;
  const s1ScoreXP = hasS1GranularProgress
    ? Math.round((s1RawScore / 17) * 50)
    : bestScores[SCENARIO_INDEX.CONTENT_AVALANCHE] * PC_SCORE_XP_PER_POINT;
  if (hasS1GranularProgress) bestScores[SCENARIO_INDEX.CONTENT_AVALANCHE] = Math.round((s1RawScore / 17) * 5);
  const otherScoreXP = bestScores.reduce((total, score, index) => (
    index === SCENARIO_INDEX.CONTENT_AVALANCHE ? total : total + (score * PC_SCORE_XP_PER_POINT)
  ), 0);
  const scoreXP = s1ScoreXP + otherScoreXP;
  const completionXP = completedAwards.filter(Boolean).length * PC_COMPLETION_XP;
  const computedXP = Math.min(PC_MAX_XP, scoreXP + completionXP);
  return { xp: computedXP, bestScores, completedAwards, s1PracticeScores, s1TransferScore };
}

function pcSaveProgressState() {
  try { localStorage.setItem(PC_PROGRESS_STORAGE_KEY, JSON.stringify(pcProgressState)); } catch (error) {}
}

function pcLoadProgressState() {
  let stored = {};
  try { stored = JSON.parse(localStorage.getItem(PC_PROGRESS_STORAGE_KEY) || '{}'); } catch (error) { stored = {}; }
  pcProgressState = pcNormalizeProgressState(stored);
  xp = pcProgressState.xp;
  return pcProgressState;
}

function pcGetEducatorLevel(xpValue = xp) {
  const safeXP = Math.max(0, Math.min(PC_MAX_XP, Number(xpValue) || 0));
  let levelIndex = 0;
  PC_EDUCATOR_LEVELS.forEach((level, index) => {
    if (safeXP >= level.threshold) levelIndex = index;
  });
  return {
    ...PC_EDUCATOR_LEVELS[levelIndex],
    index: levelIndex,
    number: levelIndex + 1,
    next: PC_EDUCATOR_LEVELS[levelIndex + 1] || null
  };
}

function pcRenderProgressHUD() {
  const progress = pcNormalizeProgressState(pcProgressState);
  pcProgressState = progress;
  xp = progress.xp;
  const level = pcGetEducatorLevel(progress.xp);
  const completedCount = progress.completedAwards.filter(Boolean).length;
  const levelStart = Number(level.threshold || 0);
  const levelEnd = level.next ? Number(level.next.threshold) : PC_MAX_XP;
  const levelSpan = Math.max(1, levelEnd - levelStart);
  const levelXP = Math.max(0, Math.min(levelSpan, progress.xp - levelStart));
  const levelPercent = Math.min(100, (levelXP / levelSpan) * 100);

  const levelTag = document.getElementById('levelTag');
  const headerLevel = document.getElementById('progressHeaderLevel');
  const xpLabel = document.getElementById('xpLabel');
  const xpFill = document.getElementById('xpFill');
  const progressbar = document.querySelector('.pc-progress-menu [role="progressbar"]');
  const levelName = document.getElementById('progressLevelName');
  const levelNumber = document.getElementById('progressLevelNumber');
  const levelDescription = document.getElementById('progressLevelDescription');
  const xpText = document.getElementById('progressXPText');
  const panelFill = document.getElementById('progressPanelFill');
  const scenarioText = document.getElementById('progressScenarioText');
  const nextLevel = document.getElementById('progressNextLevel');
  const lifetimeXP = document.getElementById('progressLifetimeXP');

  if (levelTag) levelTag.textContent = level.title;
  if (headerLevel) headerLevel.textContent = `Level ${level.number}`;
  if (xpLabel) xpLabel.textContent = level.next
    ? `${levelXP} / ${levelSpan} XP`
    : `${progress.xp} XP`;
  if (xpFill) xpFill.style.width = `${levelPercent}%`;
  if (progressbar) {
    progressbar.setAttribute('aria-valuenow', String(levelXP));
    progressbar.setAttribute('aria-valuemax', String(levelSpan));
    progressbar.setAttribute('aria-valuetext', level.next
      ? `${levelXP} of ${levelSpan} XP toward ${level.next.title}. Current level: ${level.title}.`
      : `${progress.xp} total XP. Highest teaching level reached.`);
  }
  if (levelName) levelName.textContent = level.title;
  if (levelNumber) levelNumber.textContent = `Level ${level.number}`;
  if (levelDescription) levelDescription.textContent = level.description;
  if (xpText) xpText.textContent = level.next
    ? `${levelXP} / ${levelSpan} XP to next level`
    : 'Highest teaching level reached';
  if (panelFill) panelFill.style.width = `${levelPercent}%`;
  if (scenarioText) scenarioText.textContent = `${completedCount} of ${SCENARIO_COUNT} scenarios completed`;
  if (nextLevel) nextLevel.textContent = level.next
    ? `Next: ${level.next.title}`
    : 'Progression complete';
  if (lifetimeXP) lifetimeXP.textContent = `Total XP: ${progress.xp} / ${PC_MAX_XP}`;
}

function pcInitializeProgressSystem() {
  pcLoadProgressState();
  pcRenderProgressHUD();
}

function pcResetTeachingProgress() {
  try { localStorage.removeItem(PC_PROGRESS_STORAGE_KEY); } catch (error) {}
  xp = 0;
  pcProgressState = {
    xp: 0,
    bestScores: Array(SCENARIO_COUNT).fill(0),
    completedAwards: Array(SCENARIO_COUNT).fill(false),
    s1PracticeScores: Array(4).fill(0),
    s1TransferScore: 0
  };
  scenarioCompleted = Array(SCENARIO_COUNT).fill(false);
  pcSaveProgressState();
  pcRenderProgressHUD();
  return true;
}

function pcResetScenarioTeachingProgress(index) {
  const normalizedIndex = Math.max(0, Math.min(SCENARIO_COUNT - 1, Number(index) || 0));
  const progress = pcNormalizeProgressState(pcProgressState);
  progress.bestScores[normalizedIndex] = 0;
  progress.completedAwards[normalizedIndex] = false;
  if (normalizedIndex === SCENARIO_INDEX.CONTENT_AVALANCHE) {
    progress.s1PracticeScores = Array(4).fill(0);
    progress.s1TransferScore = 0;
  }
  pcProgressState = pcNormalizeProgressState(progress);
  scenarioCompleted[normalizedIndex] = false;
  xp = pcProgressState.xp;
  pcSaveProgressState();
  pcRenderProgressHUD();
  return true;
}

function awardScenarioScoreXP(index, score, maxScore = 5) {
  const normalizedIndex = Math.max(0, Math.min(SCENARIO_COUNT - 1, Number(index) || 0));
  const normalizedMax = Math.max(1, Number(maxScore) || 5);
  const normalizedScore = Math.max(0, Math.min(normalizedMax, Number(score) || 0));
  const fivePointScore = Math.round((normalizedScore / normalizedMax) * 5);
  const previous = Number(pcProgressState.bestScores[normalizedIndex] || 0);
  if (fivePointScore <= previous) return 0;
  pcProgressState.bestScores[normalizedIndex] = fivePointScore;
  const earned = (fivePointScore - previous) * PC_SCORE_XP_PER_POINT;
  pcProgressState = pcNormalizeProgressState(pcProgressState);
  xp = pcProgressState.xp;
  pcSaveProgressState();
  pcRenderProgressHUD();
  return earned;
}

function awardScenarioCompletionXP(index) {
  const normalizedIndex = Math.max(0, Math.min(SCENARIO_COUNT - 1, Number(index) || 0));
  if (pcProgressState.completedAwards[normalizedIndex]) return 0;
  pcProgressState.completedAwards[normalizedIndex] = true;
  pcProgressState = pcNormalizeProgressState(pcProgressState);
  xp = pcProgressState.xp;
  pcSaveProgressState();
  pcRenderProgressHUD();
  return PC_COMPLETION_XP;
}

function pcAwardS1GranularXP(updateProgress) {
  const beforeXP = pcNormalizeProgressState(pcProgressState).xp;
  updateProgress();
  pcProgressState = pcNormalizeProgressState(pcProgressState);
  xp = pcProgressState.xp;
  pcSaveProgressState();
  pcRenderProgressHUD();
  return Math.max(0, pcProgressState.xp - beforeXP);
}

function awardS1PracticeXP(caseIndex, score) {
  const normalizedCase = Math.max(0, Math.min(3, Number(caseIndex) || 0));
  const normalizedScore = Math.max(0, Math.min(3, Number(score) || 0));
  return pcAwardS1GranularXP(() => {
    pcProgressState.s1PracticeScores = Array.from({ length: 4 }, (_, index) => (
      index === normalizedCase
        ? Math.max(Number(pcProgressState.s1PracticeScores?.[index] || 0), normalizedScore)
        : Number(pcProgressState.s1PracticeScores?.[index] || 0)
    ));
  });
}

function awardS1TransferXP(score) {
  const normalizedScore = Math.max(0, Math.min(5, Number(score) || 0));
  return pcAwardS1GranularXP(() => {
    pcProgressState.s1TransferScore = Math.max(Number(pcProgressState.s1TransferScore || 0), normalizedScore);
  });
}

function pcGetLevelProgressSnapshot() {
  const progress = pcNormalizeProgressState(pcProgressState);
  const level = pcGetEducatorLevel(progress.xp);
  const levelEnd = level.next ? Number(level.next.threshold) : PC_MAX_XP;
  return {
    progress,
    level,
    levelXP: Math.max(0, progress.xp - Number(level.threshold || 0)),
    levelSpan: Math.max(1, levelEnd - Number(level.threshold || 0))
  };
}

pcExposeGlobals({
  pcInitializeProgressSystem,
  pcRenderProgressHUD,
  pcGetEducatorLevel,
  pcResetTeachingProgress,
  pcResetScenarioTeachingProgress,
  awardScenarioScoreXP,
  awardScenarioCompletionXP,
  awardS1PracticeXP,
  awardS1TransferXP,
  pcGetLevelProgressSnapshot
});

